export type Operation = "load" | "publish" | "subscribe" | "endorse";
export type Status =
  | { readonly phase: "idle" }
  | { readonly phase: "pending" }
  | { readonly phase: "success" }
  | { readonly phase: "error"; readonly message: string };

export interface Note {
  readonly boardId: string;
  readonly id: string;
  readonly text: string;
}

export interface WorkspaceState {
  readonly statuses: Readonly<Record<Operation, Status>>;
  readonly notes: readonly Note[];
}

export type WorkspaceEvent =
  | { readonly type: "Begin"; readonly operation: Operation }
  | { readonly type: "Succeed"; readonly operation: Operation }
  | { readonly type: "Fail"; readonly operation: Operation; readonly message: string }
  | { readonly type: "ReplaceNotes"; readonly notes: readonly Note[] }
  | { readonly type: "RemoveNote"; readonly boardId: string; readonly noteId: string };

export function createWorkspaceState(): WorkspaceState {
  return {
    statuses: { load: { phase: "idle" }, publish: { phase: "idle" }, subscribe: { phase: "idle" }, endorse: { phase: "idle" } },
    notes: []
  };
}

export function reduceWorkspace(state: WorkspaceState, event: WorkspaceEvent): WorkspaceState {
  switch (event.type) {
    case "Begin":
      return { ...state, statuses: { ...state.statuses, [event.operation]: { phase: "pending" } } };
    case "Succeed":
      return { ...state, statuses: { ...state.statuses, [event.operation]: { phase: "success" } } };
    case "Fail":
      return { ...state, statuses: { ...state.statuses, [event.operation]: { phase: "error", message: event.message } } };
    case "ReplaceNotes":
      return { ...state, notes: event.notes.map((note) => ({ ...note })) };
    case "RemoveNote":
      return { ...state, notes: state.notes.filter((note) => note.id !== event.noteId) };
  }
}

