import { createWorkspaceState, reduceWorkspace } from './solution';
import type { Note, Operation, WorkspaceEvent, WorkspaceState } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function equal<T>(actual: T, expected: T, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}

const initial = createWorkspaceState();
for (const operation of ['load', 'publish', 'subscribe', 'endorse'] as Operation[]) {
  equal(initial.statuses[operation].phase, 'idle', `${operation} starts idle`);
}
equal(initial.notes.length, 0, 'notes start empty');

let state: WorkspaceState = initial;
const beginEvent: WorkspaceEvent = { type: 'Begin', operation: 'publish' };
state = reduceWorkspace(state, beginEvent);
equal(state.statuses.publish.phase, 'pending', 'Begin updates named operation');
equal(state.statuses.load.phase, 'idle', 'Begin leaves other operation unchanged');
equal(beginEvent.type, 'Begin', 'event is not mutated');

const beforeSucceed = state;
state = reduceWorkspace(state, { type: 'Succeed', operation: 'publish' });
equal(state.statuses.publish.phase, 'success', 'Succeed updates named operation');
equal(beforeSucceed.statuses.publish.phase, 'pending', 'prior state remains unchanged');

const beforeFail = state;
state = reduceWorkspace(state, { type: 'Fail', operation: 'subscribe', message: 'network' });
const failed = state.statuses.subscribe;
assert(failed.phase === 'error' && failed.message === 'network', 'Fail stores the error message');
equal(state.statuses.publish.phase, 'success', 'Fail leaves other status unchanged');
equal(beforeFail.statuses.subscribe.phase, 'idle', 'Fail does not mutate prior state');

const suppliedNotes: Note[] = [
  { boardId: 'board-a', id: 'same', text: 'A' },
  { boardId: 'board-b', id: 'same', text: 'B' },
  { boardId: 'board-a', id: 'other', text: 'C' }
];
const replaceEvent: WorkspaceEvent = { type: 'ReplaceNotes', notes: suppliedNotes };
const replaced = reduceWorkspace(state, replaceEvent);
assert(replaced.notes !== suppliedNotes, 'ReplaceNotes copies the array');
assert(replaced.notes.every((note, i) => note !== suppliedNotes[i]), 'ReplaceNotes copies every note');
(suppliedNotes[0] as { text: string }).text = 'mutated';
suppliedNotes.push({ boardId: 'x', id: 'x', text: 'x' });
equal(replaced.notes.length, 3, 'later input-array mutation does not affect state');
equal(replaced.notes[0].text, 'A', 'later input-note mutation does not affect state');

const removed = reduceWorkspace(replaced, { type: 'RemoveNote', boardId: 'board-a', noteId: 'same' });
equal(removed.notes.length, 2, 'one matching note removed');
equal(removed.notes[0].boardId, 'board-b', 'same ID on other board remains');
equal(removed.notes[0].id, 'same', 'remaining order is preserved');
equal(removed.notes[1].id, 'other', 'later note order is preserved');
equal(replaced.notes.length, 3, 'RemoveNote does not mutate prior notes');

const missing = reduceWorkspace(removed, { type: 'RemoveNote', boardId: 'missing', noteId: 'same' });
assert(missing.notes !== removed.notes, 'missing removal still returns fresh notes array');
equal(missing.notes.length, removed.notes.length, 'missing removal preserves content length');
assert(missing.notes.every((note, i) => note === removed.notes[i]), 'missing removal preserves equivalent ordered content');

